import os
import logging
import socketio
import functools
import asyncio

from concurrent.futures import ThreadPoolExecutor

from codx.junior.sio.session_channel import SessionChannel
from codx.junior.engine import CODXJuniorSession

from codx.junior.context import (
    AICodeGenerator
)

from codx.junior.sio.model import (
    SioMessage,
    SioChatMessage
)

from codx.junior.ai import AIManager
from codx.junior.security.user_management import get_authenticated_user_from_token

CODX_JUNIOR_API_BACKGROUND = os.environ.get("CODX_JUNIOR_API_BACKGROUND")

USERS = {}

logger = logging.getLogger(__name__)

#Socket io (sio) create a Socket.IO server
sio = socketio.AsyncServer(cors_allowed_origins='*', async_mode='asgi')

SIO_POOL = ThreadPoolExecutor(max_workers=10)

def sio_api_endpoint(func):
    """Decorator to process sio API requests."""
    @functools.wraps(func)
    async def wrapper(sid: str, data: dict):
        logger.info(f"SIO REquest {sid} {data}")
        base_data = SioMessage(**data)
        channel = SessionChannel(sio=sio, sid=sid)
        user = get_authenticated_user_from_token(USERS[sid]["user"]["token"])
        codxjunior_session = CODXJuniorSession(
                                channel=channel,
                                user=user,
                                codx_path=base_data.codx_path) if base_data.codx_path \
                                  else None # Global requests
        try:
            if not asyncio.iscoroutinefunction(func):
                return SIO_POOL.submit(func, sid, data, codxjunior_session).result
            else:
                def worker():
                    try:
                        return asyncio.run(func(sid, data, codxjunior_session))
                    except Exception as ex:
                        logger.exception(f"Error processing async sio message")
                    return None
                return SIO_POOL.submit(worker)
        except Exception as ex:
            logger.exception(f"Error processing sio message")
        return None
    return wrapper

async def sio_send_event(event, data):
    return await sio.emit(event, data)

@sio.on("error")
async def error():
    logger.error(f"Socket error")

@sio.on("connect")
async def connect(sid, env):
    logger.info("New Client Connected to This id :"+" "+str(sid))

@sio.on("disconnect")
async def disconnect(sid):
    logger.info("Client Disconnected: "+" "+str(sid))
    if USERS.get(sid):
        del USERS[sid]
    send_online_users(sid)  

def send_online_users(sid):
    channel = SessionChannel(sio=sio, sid=sid)
    online_users = [{
      "username": USERS[sid]["user"].get("username"),
      "avatar": USERS[sid]["user"].get("avatar"),
      "sid": sid
    } for sid in USERS.keys() if USERS.get("sid",{}).get("user")]
    channel.send_event('codx-junior-online-users', { "users": online_users })

@sio.on("codx-junior-ping")
async def io_ping(sid, data: dict = None):
    return True


@sio.on("background-event")
async def on_background_event(sid, data: dict):
    # logger.info(f"***************** On event bacground: {data}")
    event = data["event"]
    if event == "hello":
        return f"Hi! Is back: {CODX_JUNIOR_API_BACKGROUND}"
    await sio_send_event(data["event"], data["data"])

@sio.on("codx-junior-login")
def io_login(sid, data: dict):
    USERS[sid] = data
    send_online_users(sid)

@sio.on("codx-junior-chat")
@sio_api_endpoint
async def io_chat(sid, data: dict, codxjunior_session: CODXJuniorSession):
    data = SioChatMessage(**data)
    logger.info(f"codx-junior-chat {data.chat.name} {codxjunior_session.settings.project_name}")
    codxjunior_session.event_manager.chat_event(chat=data.chat, message="Chatting with project...")
    await codxjunior_session.chat_with_project(chat_id=data.chat.id, owner_project_id=data.chat.owner_project_id)

@sio.on("codx-junior-chat-search")
@sio_api_endpoint
async def io_chat_search(sid, msg_data: dict, codxjunior_session: CODXJuniorSession):
    data = SioChatMessage(**msg_data)
    logger.info(f"codx-junior-chat-search {data.chat.name} {codxjunior_session.settings.project_name}")
    codxjunior_session.event_manager.chat_event(chat=data.chat, message="Chat search...")
    chat_id = data.chat.id
    query = msg_data["query"]
    await codxjunior_session.chat_search(chat_id=chat_id, query=query)

@sio.on("codx-junior-subtasks")
@sio_api_endpoint
async def io_chat_subtasks(sid, data: dict, codxjunior_session: CODXJuniorSession):
    sio_chat = SioChatMessage(**data)
    instructions = data.get("instructions")
    return await codxjunior_session.generate_tasks(chat=sio_chat.chat, 
                                                    instructions=instructions)

@sio.on("codx-junior-improve")
@sio_api_endpoint
async def io_run_improve(sid, data: dict, codxjunior_session: CODXJuniorSession):
    data = SioChatMessage(**data)
    await codxjunior_session.improve_existing_code(chat=data.chat)

@sio.on("codx-junior-generate-tasks")
@sio_api_endpoint
async def io_create_chat_tasks(sid, data: dict, codxjunior_session: CODXJuniorSession):
    data = SioChatMessage(**data)
    await codxjunior_session.generate_tasks(chat=data.chat)

@sio.on("codx-junior-improve-patch")
@sio_api_endpoint
async def sio_run_improve_patch(sid, data: dict, codxjunior_session: CODXJuniorSession):
    code_generator = AICodeGenerator(**data["code_generator"])
    data = SioChatMessage(**data)
    info, error = await codxjunior_session.improve_existing_code_patch(
                            chat=data.chat,
                            code_generator=code_generator)
    return {
        "info": info, 
        "error": error
    }

@sio.on("codx-junior-generate-code")
@sio_api_endpoint
async def sio_run_generate_code(sid, data: dict, codxjunior_session: CODXJuniorSession):
    code_block_info = data["code_block_info"]
    data = SioChatMessage(**data)
    await codxjunior_session.generate_code(
                            chat=data.chat,
                            code_block_info=code_block_info)

@sio.on("codx-junior-ai-load-model")
@sio_api_endpoint
async def sio_ai_load_model(sid, data: dict):
    AIManager().load_model(model=data["model"])


# ============================================================================
# Browser Session Events (Long-running operations via Socket.IO)
# ============================================================================

@sio.on("codx-junior-browser-create")
@sio_api_endpoint
async def sio_browser_create(sid, data: dict, codxjunior_session: CODXJuniorSession):
    """
    Create a new browser session via Socket.IO.
    Sends real-time status updates as the session starts.

    Request data:
        - chat_id: str - Associated chat ID

    Emits events:
        - codx-junior-browser-status: {status, session_id, message, error}
    """
    channel = SessionChannel(sio=sio, sid=sid)
    chat_id = data.get("chat_id")

    if not chat_id:
        logger.error("sio_browser_create: chat_id is required")
        channel.send_event("codx-junior-browser-status", {
            "status": "error",
            "message": "chat_id is required",
            "error": "Missing chat_id"
        })
        return

    try:
        from codx.junior.browser.browser_manager import BrowserManager
        from codx.junior.chat_manager import ChatManager

        # Validate chat exists
        chat_manager = ChatManager(codxjunior_session.settings)
        chat = chat_manager.find_by_id(chat_id)
        if not chat:
            logger.error("sio_browser_create: chat not found: %s", chat_id)
            channel.send_event("codx-junior-browser-status", {
                "status": "error",
                "message": "Chat not found",
                "error": f"Chat {chat_id} not found"
            })
            return

        # Emit starting event
        channel.send_event("codx-junior-browser-status", {
            "status": "starting",
            "message": "Creating browser session...",
            "chat_id": chat_id
        })

        # Create browser session
        browser_manager = BrowserManager(codxjunior_session.settings)
        browser_session = browser_manager.create_session(chat_id)

        # Emit creation event
        channel.send_event("codx-junior-browser-status", {
            "status": "created",
            "session_id": browser_session.id,
            "message": f"Browser session {browser_session.id[:8]} created",
            "session": browser_session.to_dict()
        })

        # Emit starting container event
        channel.send_event("codx-junior-browser-status", {
            "status": "starting_container",
            "session_id": browser_session.id,
            "message": "Starting Docker container...",
            "container_id": browser_session.container_id
        })

        # Sync to chat metadata
        browser_manager.save_session_to_chat(browser_session, chat)
        chat_manager.save_chat(chat)

        # Emit ready event
        channel.send_event("codx-junior-browser-status", {
            "status": "ready",
            "session_id": browser_session.id,
            "message": f"Browser session ready",
            "session": browser_session.to_dict()
        })

        logger.info(
            "sio_browser_create: created session %s for chat %s",
            browser_session.id[:8],
            chat_id
        )

    except Exception as e:
        logger.exception("sio_browser_create: unexpected error: %s", e)
        channel.send_event("codx-junior-browser-status", {
            "status": "error",
            "message": "Failed to create browser session",
            "error": str(e)
        })


@sio.on("codx-junior-browser-delete")
@sio_api_endpoint
async def sio_browser_delete(sid, data: dict, codxjunior_session: CODXJuniorSession):
    """
    Delete a browser session via Socket.IO.
    Sends real-time status updates as the session stops.

    Request data:
        - session_id: str - Session ID to delete

    Emits events:
        - codx-junior-browser-status: {status, session_id, message, error}
    """
    channel = SessionChannel(sio=sio, sid=sid)
    session_id = data.get("session_id")

    if not session_id:
        logger.error("sio_browser_delete: session_id is required")
        channel.send_event("codx-junior-browser-status", {
            "status": "error",
            "message": "session_id is required",
            "error": "Missing session_id"
        })
        return

    try:
        from codx.junior.browser.browser_manager import BrowserManager

        browser_manager = BrowserManager(codxjunior_session.settings)

        # Emit stopping event
        channel.send_event("codx-junior-browser-status", {
            "status": "stopping",
            "session_id": session_id,
            "message": "Stopping browser session..."
        })

        browser_session = browser_manager.get_session(session_id)
        if not browser_session:
            logger.error("sio_browser_delete: session not found: %s", session_id)
            channel.send_event("codx-junior-browser-status", {
                "status": "error",
                "session_id": session_id,
                "message": "Session not found",
                "error": f"Session {session_id} not found"
            })
            return

        # Delete session
        browser_manager.delete_session(session_id)

        # Emit deleted event
        channel.send_event("codx-junior-browser-status", {
            "status": "deleted",
            "session_id": session_id,
            "message": f"Browser session {session_id[:8]} deleted"
        })

        logger.info("sio_browser_delete: deleted session %s", session_id[:8])

    except Exception as e:
        logger.exception("sio_browser_delete: unexpected error: %s", e)
        channel.send_event("codx-junior-browser-status", {
            "status": "error",
            "session_id": session_id,
            "message": "Failed to delete browser session",
            "error": str(e)
        })


@sio.on("codx-junior-browser-restart")
@sio_api_endpoint
async def sio_browser_restart(sid, data: dict, codxjunior_session: CODXJuniorSession):
    """
    Restart a browser session via Socket.IO.
    Sends real-time status updates as the session restarts.

    Request data:
        - session_id: str - Session ID to restart

    Emits events:
        - codx-junior-browser-status: {status, session_id, message, error}
    """
    channel = SessionChannel(sio=sio, sid=sid)
    session_id = data.get("session_id")

    if not session_id:
        logger.error("sio_browser_restart: session_id is required")
        channel.send_event("codx-junior-browser-status", {
            "status": "error",
            "message": "session_id is required",
            "error": "Missing session_id"
        })
        return

    try:
        from codx.junior.browser.browser_manager import BrowserManager

        browser_manager = BrowserManager(codxjunior_session.settings)

        # Emit restarting event
        channel.send_event("codx-junior-browser-status", {
            "status": "restarting",
            "session_id": session_id,
            "message": "Restarting browser session..."
        })

        browser_session = await browser_manager.restart_session(session_id)
        if not browser_session:
            logger.error("sio_browser_restart: session not found: %s", session_id)
            channel.send_event("codx-junior-browser-status", {
                "status": "error",
                "session_id": session_id,
                "message": "Session not found",
                "error": f"Session {session_id} not found"
            })
            return

        # Emit ready event
        channel.send_event("codx-junior-browser-status", {
            "status": "ready",
            "session_id": session_id,
            "message": f"Browser session {session_id[:8]} restarted",
            "session": browser_session.to_dict()
        })

        logger.info("sio_browser_restart: restarted session %s", session_id[:8])

    except Exception as e:
        logger.exception("sio_browser_restart: unexpected error: %s", e)
        channel.send_event("codx-junior-browser-status", {
            "status": "error",
            "session_id": session_id,
            "message": "Failed to restart browser session",
            "error": str(e)
        })


@sio.on("codx-junior-browser-stop")
@sio_api_endpoint
async def sio_browser_stop(sid, data: dict, codxjunior_session: CODXJuniorSession):
    """
    Stop a browser session (without deleting) via Socket.IO.
    Sends real-time status updates as the session stops.

    Request data:
        - session_id: str - Session ID to stop

    Emits events:
        - codx-junior-browser-status: {status, session_id, message, error}
    """
    channel = SessionChannel(sio=sio, sid=sid)
    session_id = data.get("session_id")

    if not session_id:
        logger.error("sio_browser_stop: session_id is required")
        channel.send_event("codx-junior-browser-status", {
            "status": "error",
            "message": "session_id is required",
            "error": "Missing session_id"
        })
        return

    try:
        from codx.junior.browser.browser_manager import BrowserManager

        browser_manager = BrowserManager(codxjunior_session.settings)

        # Emit stopping event
        channel.send_event("codx-junior-browser-status", {
            "status": "stopping",
            "session_id": session_id,
            "message": "Stopping browser session..."
        })

        browser_session = browser_manager.get_session(session_id)
        if not browser_session:
            logger.error("sio_browser_stop: session not found: %s", session_id)
            channel.send_event("codx-junior-browser-status", {
                "status": "error",
                "session_id": session_id,
                "message": "Session not found",
                "error": f"Session {session_id} not found"
            })
            return

        # Stop the browser container
        if hasattr(browser_manager, 'stop_session'):
            browser_manager.stop_session(session_id)

        # Emit stopped event
        channel.send_event("codx-junior-browser-status", {
            "status": "stopped",
            "session_id": session_id,
            "message": f"Browser session {session_id[:8]} stopped"
        })

        logger.info("sio_browser_stop: stopped session %s", session_id[:8])

    except Exception as e:
        logger.exception("sio_browser_stop: unexpected error: %s", e)
        channel.send_event("codx-jupyter-browser-status", {
            "status": "error",
            "session_id": session_id,
            "message": "Failed to stop browser session",
            "error": str(e)
        })

